export type SafeToolPresenceArgumentKey = Extract<
	SafeToolArgumentKey,
	| "date"
	| "end_date"
	| "exercise_template_id"
	| "folder_id"
	| "primary_muscle_group"
	| "query"
	| "routine_id"
